CREATE TABLE `company` (
	`owner` text PRIMARY KEY NOT NULL,
	`data` text NOT NULL
);

CREATE TRIGGER guard_allocation BEFORE INSERT ON allocations BEGIN
 SELECT CASE WHEN NEW.amount <= 0 OR NOT EXISTS(SELECT 1 FROM records WHERE id=NEW.installment_id AND owner=NEW.owner AND kind='installments' AND archived=0) OR NOT EXISTS(SELECT 1 FROM records WHERE id=NEW.payment_id AND owner=NEW.owner AND kind='payments' AND json_extract(data,'$.status')='cleared' AND json_extract(data,'$.amount')=NEW.amount AND json_extract(data,'$.direction')='incoming' AND json_extract(data,'$.installmentId')=NEW.installment_id AND json_extract(data,'$.clientId')=(SELECT json_extract(data,'$.clientId') FROM records WHERE id=NEW.installment_id)) THEN RAISE(ABORT,'invalid_allocation') END;
 SELECT CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM allocations WHERE installment_id=NEW.installment_id)+NEW.amount > (SELECT json_extract(data,'$.amount') FROM records WHERE id=NEW.installment_id) THEN RAISE(ABORT,'overpayment') END;
END;

CREATE TRIGGER payment_insert AFTER INSERT ON records WHEN NEW.kind='payments' AND json_extract(NEW.data,'$.status')='cleared' AND json_extract(NEW.data,'$.installmentId') IS NOT NULL BEGIN
 INSERT INTO allocations(id,payment_id,installment_id,owner,amount) VALUES(NEW.id,NEW.id,json_extract(NEW.data,'$.installmentId'),NEW.owner,json_extract(NEW.data,'$.amount'));
END;

CREATE TRIGGER payment_clear AFTER UPDATE ON records WHEN NEW.kind='payments' AND json_extract(OLD.data,'$.status')!='cleared' AND json_extract(NEW.data,'$.status')='cleared' AND json_extract(NEW.data,'$.installmentId') IS NOT NULL BEGIN
 INSERT INTO allocations(id,payment_id,installment_id,owner,amount) VALUES(NEW.id,NEW.id,json_extract(NEW.data,'$.installmentId'),NEW.owner,json_extract(NEW.data,'$.amount'));
END;

CREATE TRIGGER payment_cancel AFTER UPDATE ON records WHEN NEW.kind='payments' AND json_extract(OLD.data,'$.status')='cleared' AND json_extract(NEW.data,'$.status')='cancelled' BEGIN
 DELETE FROM allocations WHERE payment_id=NEW.id;
END;

CREATE TRIGGER stock_movement AFTER INSERT ON records WHEN NEW.kind='movements' BEGIN
 INSERT INTO stock_balances(owner,product_id,warehouse,quantity) VALUES(NEW.owner,json_extract(NEW.data,'$.productId'),json_extract(NEW.data,'$.warehouse'),0) ON CONFLICT DO NOTHING;
 UPDATE stock_balances SET quantity=quantity+CAST(ROUND(json_extract(NEW.data,'$.quantity')*1000) AS INTEGER) * CASE WHEN json_extract(NEW.data,'$.direction')='stockIn' THEN 1 ELSE -1 END WHERE owner=NEW.owner AND product_id=json_extract(NEW.data,'$.productId') AND warehouse=json_extract(NEW.data,'$.warehouse');
END;

CREATE TRIGGER guard_mission_insert BEFORE INSERT ON records WHEN NEW.kind='missions' AND json_extract(NEW.data,'$.status') IN ('planned','confirmed') BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE kind='missions' AND archived=0 AND owner=NEW.owner AND json_extract(data,'$.vehicleId')=json_extract(NEW.data,'$.vehicleId') AND json_extract(data,'$.date')=json_extract(NEW.data,'$.date') AND json_extract(data,'$.status') IN ('planned','confirmed') AND json_extract(data,'$.time') < json_extract(NEW.data,'$.returnTime') AND json_extract(data,'$.returnTime') > json_extract(NEW.data,'$.time')) THEN RAISE(ABORT,'vehicle_overlap') END;
END;

CREATE TRIGGER guard_mission_update BEFORE UPDATE ON records WHEN NEW.kind='missions' AND json_extract(NEW.data,'$.status') IN ('planned','confirmed') BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE kind='missions' AND archived=0 AND owner=NEW.owner AND id!=NEW.id AND json_extract(data,'$.vehicleId')=json_extract(NEW.data,'$.vehicleId') AND json_extract(data,'$.date')=json_extract(NEW.data,'$.date') AND json_extract(data,'$.status') IN ('planned','confirmed') AND json_extract(data,'$.time') < json_extract(NEW.data,'$.returnTime') AND json_extract(data,'$.returnTime') > json_extract(NEW.data,'$.time')) THEN RAISE(ABORT,'vehicle_overlap') END;
END;

CREATE TRIGGER mission_km_insert AFTER INSERT ON records WHEN NEW.kind='missions' AND json_extract(NEW.data,'$.status')='completed' AND json_extract(NEW.data,'$.endKm') IS NOT NULL BEGIN
 UPDATE records SET data=json_set(data,'$.odometer',MAX(COALESCE(json_extract(data,'$.odometer'),0),json_extract(NEW.data,'$.endKm'))),revision=revision+1,updated_at=NEW.updated_at WHERE id=json_extract(NEW.data,'$.vehicleId') AND owner=NEW.owner AND kind='vehicles';
END;

CREATE TRIGGER mission_km_update AFTER UPDATE ON records WHEN NEW.kind='missions' AND json_extract(OLD.data,'$.status')!='completed' AND json_extract(NEW.data,'$.status')='completed' AND json_extract(NEW.data,'$.endKm') IS NOT NULL BEGIN
 UPDATE records SET data=json_set(data,'$.odometer',MAX(COALESCE(json_extract(data,'$.odometer'),0),json_extract(NEW.data,'$.endKm'))),revision=revision+1,updated_at=NEW.updated_at WHERE id=json_extract(NEW.data,'$.vehicleId') AND owner=NEW.owner AND kind='vehicles';
END;

CREATE TRIGGER reservation_insert BEFORE INSERT ON records WHEN NEW.kind='reservations' AND json_extract(NEW.data,'$.status')='reserved' BEGIN
 SELECT CASE WHEN COALESCE((SELECT quantity FROM stock_balances WHERE owner=NEW.owner AND product_id=json_extract(NEW.data,'$.productId') AND warehouse=json_extract(NEW.data,'$.warehouse')),0) - COALESCE((SELECT SUM(CAST(ROUND(json_extract(data,'$.quantity')*1000) AS INTEGER)) FROM records WHERE owner=NEW.owner AND kind='reservations' AND archived=0 AND json_extract(data,'$.status')='reserved' AND json_extract(data,'$.productId')=json_extract(NEW.data,'$.productId') AND json_extract(data,'$.warehouse')=json_extract(NEW.data,'$.warehouse')),0) < CAST(ROUND(json_extract(NEW.data,'$.quantity')*1000) AS INTEGER) THEN RAISE(ABORT,'insufficient_available_stock') END;
END;

CREATE TRIGGER reservation_update BEFORE UPDATE ON records WHEN NEW.kind='reservations' AND json_extract(NEW.data,'$.status')='reserved' AND NEW.archived=0 BEGIN
 SELECT CASE WHEN COALESCE((SELECT quantity FROM stock_balances WHERE owner=NEW.owner AND product_id=json_extract(NEW.data,'$.productId') AND warehouse=json_extract(NEW.data,'$.warehouse')),0) - COALESCE((SELECT SUM(CAST(ROUND(json_extract(data,'$.quantity')*1000) AS INTEGER)) FROM records WHERE owner=NEW.owner AND kind='reservations' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.status')='reserved' AND json_extract(data,'$.productId')=json_extract(NEW.data,'$.productId') AND json_extract(data,'$.warehouse')=json_extract(NEW.data,'$.warehouse')),0) < CAST(ROUND(json_extract(NEW.data,'$.quantity')*1000) AS INTEGER) THEN RAISE(ABORT,'insufficient_available_stock') END;
END;

CREATE TRIGGER available_stock_out BEFORE INSERT ON records WHEN NEW.kind='movements' AND json_extract(NEW.data,'$.direction')='stockOut' BEGIN
 SELECT CASE WHEN COALESCE((SELECT quantity FROM stock_balances WHERE owner=NEW.owner AND product_id=json_extract(NEW.data,'$.productId') AND warehouse=json_extract(NEW.data,'$.warehouse')),0) - COALESCE((SELECT SUM(CAST(ROUND(json_extract(data,'$.quantity')*1000) AS INTEGER)) FROM records WHERE owner=NEW.owner AND kind='reservations' AND archived=0 AND json_extract(data,'$.status')='reserved' AND json_extract(data,'$.productId')=json_extract(NEW.data,'$.productId') AND json_extract(data,'$.warehouse')=json_extract(NEW.data,'$.warehouse')),0) < CAST(ROUND(json_extract(NEW.data,'$.quantity')*1000) AS INTEGER) THEN RAISE(ABORT,'insufficient_available_stock') END;
END;

CREATE TRIGGER serial_in_guard BEFORE INSERT ON records WHEN NEW.kind='movements' AND json_extract(NEW.data,'$.direction')='stockIn' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.data,'$.serialList') AS item JOIN serial_locations AS serial ON serial.owner=NEW.owner AND serial.serial=item.value WHERE serial.warehouse IS NOT NULL OR serial.product_id!=json_extract(NEW.data,'$.productId')) THEN RAISE(ABORT,'serial_location') END;
END;

CREATE TRIGGER serial_out_guard BEFORE INSERT ON records WHEN NEW.kind='movements' AND json_extract(NEW.data,'$.direction')='stockOut' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.data,'$.serialList') AS item WHERE NOT EXISTS(SELECT 1 FROM serial_locations AS serial WHERE serial.owner=NEW.owner AND serial.serial=item.value AND serial.warehouse=json_extract(NEW.data,'$.warehouse') AND serial.product_id=json_extract(NEW.data,'$.productId'))) THEN RAISE(ABORT,'serial_location') END;
END;

CREATE TRIGGER serial_in AFTER INSERT ON records WHEN NEW.kind='movements' AND json_extract(NEW.data,'$.direction')='stockIn' BEGIN
 INSERT INTO serial_locations(id,owner,serial,product_id,warehouse,project_id,last_movement) SELECT lower(hex(randomblob(16))),NEW.owner,value,json_extract(NEW.data,'$.productId'),json_extract(NEW.data,'$.warehouse'),NULL,NEW.id FROM json_each(NEW.data,'$.serialList') WHERE true ON CONFLICT(owner,serial) DO UPDATE SET warehouse=excluded.warehouse,project_id=NULL,last_movement=excluded.last_movement;
END;

CREATE TRIGGER serial_out AFTER INSERT ON records WHEN NEW.kind='movements' AND json_extract(NEW.data,'$.direction')='stockOut' BEGIN
 UPDATE serial_locations SET warehouse=NULL,project_id=json_extract(NEW.data,'$.projectId'),last_movement=NEW.id WHERE owner=NEW.owner AND serial IN (SELECT value FROM json_each(NEW.data,'$.serialList'));
END;

CREATE TRIGGER operation_guard BEFORE INSERT ON operation_guards BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM records WHERE id=NEW.record_id AND owner=NEW.owner AND revision=NEW.revision AND archived=0) THEN RAISE(ABORT,'conflict') END;
END;

CREATE TRIGGER guard_allocation BEFORE INSERT ON allocations BEGIN
 SELECT CASE WHEN NEW.amount<=0 OR typeof(NEW.amount)!='integer' OR NOT EXISTS(SELECT 1 FROM records WHERE id=NEW.installment_id AND owner=NEW.owner AND kind='installments' AND archived=0) OR NOT EXISTS(SELECT 1 FROM records p JOIN records i ON i.id=NEW.installment_id WHERE p.id=NEW.payment_id AND p.owner=NEW.owner AND p.kind='payments' AND json_extract(p.data,'$.status')='cleared' AND json_extract(p.data,'$.direction')='incoming' AND json_extract(p.data,'$.clientId')=json_extract(i.data,'$.clientId')) THEN RAISE(ABORT,'invalid_allocation') END;
 SELECT CASE WHEN COALESCE((SELECT SUM(amount) FROM allocations WHERE payment_id=NEW.payment_id),0)+NEW.amount>(SELECT json_extract(data,'$.amount') FROM records WHERE id=NEW.payment_id) THEN RAISE(ABORT,'invalid_allocation') END;
 SELECT CASE WHEN COALESCE((SELECT SUM(amount) FROM allocations WHERE installment_id=NEW.installment_id),0)+NEW.amount>(SELECT json_extract(data,'$.amount') FROM records WHERE id=NEW.installment_id) THEN RAISE(ABORT,'overpayment') END;
END;

CREATE TRIGGER payment_multi_insert AFTER INSERT ON records WHEN NEW.kind='payments' AND json_extract(NEW.data,'$.status')='cleared' AND json_array_length(NEW.data,'$.allocations')>0 BEGIN
 INSERT INTO allocations(id,payment_id,installment_id,owner,amount) SELECT NEW.id||'-'||key,NEW.id,json_extract(value,'$.installmentId'),NEW.owner,json_extract(value,'$.amount') FROM json_each(NEW.data,'$.allocations');
END;

CREATE TRIGGER payment_multi_clear AFTER UPDATE ON records WHEN NEW.kind='payments' AND json_extract(OLD.data,'$.status')!='cleared' AND json_extract(NEW.data,'$.status')='cleared' AND json_array_length(NEW.data,'$.allocations')>0 BEGIN
 INSERT INTO allocations(id,payment_id,installment_id,owner,amount) SELECT NEW.id||'-'||key,NEW.id,json_extract(value,'$.installmentId'),NEW.owner,json_extract(value,'$.amount') FROM json_each(NEW.data,'$.allocations');
END;

CREATE TRIGGER journal_insert_guard BEFORE INSERT ON records WHEN NEW.kind='journalEntries' AND json_extract(NEW.data,'$.status')='posted' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind='fiscalPeriods' AND archived=0 AND json_extract(data,'$.status')='closed' AND json_extract(NEW.data,'$.date') BETWEEN json_extract(data,'$.startDate') AND json_extract(data,'$.endDate')) THEN RAISE(ABORT,'period_closed') END;
 SELECT CASE WHEN COALESCE((SELECT SUM(COALESCE(json_extract(value,'$.debit'),0))-SUM(COALESCE(json_extract(value,'$.credit'),0)) FROM json_each(NEW.data,'$.rows')),1)!=0 THEN RAISE(ABORT,'unbalanced_entry') END;
 SELECT CASE WHEN json_array_length(NEW.data,'$.rows')<2 OR EXISTS(SELECT 1 FROM json_each(NEW.data,'$.rows') r WHERE COALESCE(json_extract(r.value,'$.debit'),0)<0 OR COALESCE(json_extract(r.value,'$.credit'),0)<0 OR (COALESCE(json_extract(r.value,'$.debit'),0)=0 AND COALESCE(json_extract(r.value,'$.credit'),0)=0) OR (COALESCE(json_extract(r.value,'$.debit'),0)>0 AND COALESCE(json_extract(r.value,'$.credit'),0)>0) OR NOT EXISTS(SELECT 1 FROM records a WHERE a.owner=NEW.owner AND a.id=json_extract(r.value,'$.accountId') AND a.kind='accounts' AND archived=0 AND json_extract(a.data,'$.status')='active')) THEN RAISE(ABORT,'invalid_journal_line') END;
END;

CREATE TRIGGER journal_update_guard BEFORE UPDATE ON records WHEN NEW.kind='journalEntries' BEGIN
 SELECT CASE WHEN json_extract(NEW.data,'$.status')='posted' AND (json_array_length(NEW.data,'$.rows')<2 OR EXISTS(SELECT 1 FROM json_each(NEW.data,'$.rows') r WHERE COALESCE(json_extract(r.value,'$.debit'),0)<0 OR COALESCE(json_extract(r.value,'$.credit'),0)<0 OR (COALESCE(json_extract(r.value,'$.debit'),0)=0 AND COALESCE(json_extract(r.value,'$.credit'),0)=0) OR (COALESCE(json_extract(r.value,'$.debit'),0)>0 AND COALESCE(json_extract(r.value,'$.credit'),0)>0) OR NOT EXISTS(SELECT 1 FROM records a WHERE a.owner=NEW.owner AND a.id=json_extract(r.value,'$.accountId') AND a.kind='accounts' AND archived=0 AND json_extract(a.data,'$.status')='active')) ) THEN RAISE(ABORT,'invalid_journal_line') END;
 SELECT CASE WHEN json_extract(OLD.data,'$.status')='posted' THEN RAISE(ABORT,'immutable') END;
 SELECT CASE WHEN json_extract(NEW.data,'$.status')='posted' AND EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind='fiscalPeriods' AND archived=0 AND json_extract(data,'$.status')='closed' AND json_extract(NEW.data,'$.date') BETWEEN json_extract(data,'$.startDate') AND json_extract(data,'$.endDate')) THEN RAISE(ABORT,'period_closed') END;
 SELECT CASE WHEN json_extract(NEW.data,'$.status')='posted' AND COALESCE((SELECT SUM(COALESCE(json_extract(value,'$.debit'),0))-SUM(COALESCE(json_extract(value,'$.credit'),0)) FROM json_each(NEW.data,'$.rows')),1)!=0 THEN RAISE(ABORT,'unbalanced_entry') END;
END;

CREATE TRIGGER leave_insert_guard BEFORE INSERT ON records WHEN NEW.kind='leave' AND json_extract(NEW.data,'$.status')='approved' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind='leave' AND archived=0 AND json_extract(data,'$.status')='approved' AND json_extract(data,'$.employeeId')=json_extract(NEW.data,'$.employeeId') AND json_extract(data,'$.startDate')<=json_extract(NEW.data,'$.endDate') AND json_extract(data,'$.endDate')>=json_extract(NEW.data,'$.startDate')) THEN RAISE(ABORT,'leave_overlap') END;
 SELECT CASE WHEN json_extract(NEW.data,'$.type')='paidLeave' AND COALESCE((SELECT SUM(json_extract(data,'$.days')) FROM records WHERE owner=NEW.owner AND kind='leave' AND archived=0 AND json_extract(data,'$.status')='approved' AND json_extract(data,'$.type')='paidLeave' AND json_extract(data,'$.employeeId')=json_extract(NEW.data,'$.employeeId') AND substr(json_extract(data,'$.startDate'),1,4)=substr(json_extract(NEW.data,'$.startDate'),1,4)),0)+json_extract(NEW.data,'$.days')>json_extract(NEW.data,'$.annualLeaveLimit') THEN RAISE(ABORT,'insufficient_leave') END;
END;

CREATE TRIGGER leave_update_guard BEFORE UPDATE ON records WHEN NEW.kind='leave' AND json_extract(NEW.data,'$.status')='approved' AND NEW.archived=0 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind='leave' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.status')='approved' AND json_extract(data,'$.employeeId')=json_extract(NEW.data,'$.employeeId') AND json_extract(data,'$.startDate')<=json_extract(NEW.data,'$.endDate') AND json_extract(data,'$.endDate')>=json_extract(NEW.data,'$.startDate')) THEN RAISE(ABORT,'leave_overlap') END;
 SELECT CASE WHEN json_extract(NEW.data,'$.type')='paidLeave' AND COALESCE((SELECT SUM(json_extract(data,'$.days')) FROM records WHERE owner=NEW.owner AND kind='leave' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.status')='approved' AND json_extract(data,'$.type')='paidLeave' AND json_extract(data,'$.employeeId')=json_extract(NEW.data,'$.employeeId') AND substr(json_extract(data,'$.startDate'),1,4)=substr(json_extract(NEW.data,'$.startDate'),1,4)),0)+json_extract(NEW.data,'$.days')>json_extract(NEW.data,'$.annualLeaveLimit') THEN RAISE(ABORT,'insufficient_leave') END;
END;

CREATE TRIGGER stock_count_guard BEFORE INSERT ON stock_guards BEGIN
 SELECT CASE WHEN COALESCE((SELECT quantity FROM stock_balances WHERE owner=NEW.owner AND product_id=NEW.product_id AND warehouse=NEW.warehouse),0)!=NEW.quantity THEN RAISE(ABORT,'conflict') END;
END;

CREATE TRIGGER fiscalperiods_insert_overlap BEFORE INSERT ON records WHEN NEW.kind='fiscalPeriods' AND NEW.archived=0 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind=NEW.kind AND id!=NEW.id AND archived=0 AND json_extract(data,'$.startDate')<=json_extract(NEW.data,'$.endDate') AND json_extract(data,'$.endDate')>=json_extract(NEW.data,'$.startDate')) THEN RAISE(ABORT,'period_overlap') END;
END;

CREATE TRIGGER fiscalperiods_update_overlap BEFORE UPDATE ON records WHEN NEW.kind='fiscalPeriods' AND NEW.archived=0 BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind=NEW.kind AND id!=NEW.id AND archived=0 AND json_extract(data,'$.startDate')<=json_extract(NEW.data,'$.endDate') AND json_extract(data,'$.endDate')>=json_extract(NEW.data,'$.startDate')) THEN RAISE(ABORT,'period_overlap') END;
END;

CREATE TRIGGER payrollpolicies_insert_overlap BEFORE INSERT ON records WHEN NEW.kind='payrollPolicies' AND NEW.archived=0 AND json_extract(NEW.data,'$.status')='validated' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind=NEW.kind AND id!=NEW.id AND archived=0 AND json_extract(data,'$.status')='validated' AND json_extract(data,'$.startDate')<=json_extract(NEW.data,'$.endDate') AND json_extract(data,'$.endDate')>=json_extract(NEW.data,'$.startDate')) THEN RAISE(ABORT,'policy_overlap') END;
END;

CREATE TRIGGER payrollpolicies_update_overlap BEFORE UPDATE ON records WHEN NEW.kind='payrollPolicies' AND NEW.archived=0 AND json_extract(NEW.data,'$.status')='validated' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM records WHERE owner=NEW.owner AND kind=NEW.kind AND id!=NEW.id AND archived=0 AND json_extract(data,'$.status')='validated' AND json_extract(data,'$.startDate')<=json_extract(NEW.data,'$.endDate') AND json_extract(data,'$.endDate')>=json_extract(NEW.data,'$.startDate')) THEN RAISE(ABORT,'policy_overlap') END;
END;

CREATE TRIGGER restructure_conservation BEFORE UPDATE ON records WHEN NEW.kind='installments' BEGIN
 SELECT CASE WHEN json_extract(NEW.data,'$.amount')<COALESCE((SELECT SUM(amount) FROM allocations WHERE installment_id=NEW.id AND owner=NEW.owner),0) OR (json_extract(NEW.data,'$.status')='restructured' AND json_extract(NEW.data,'$.amount')!=COALESCE((SELECT SUM(amount) FROM allocations WHERE installment_id=NEW.id AND owner=NEW.owner),0)) THEN RAISE(ABORT,'conflict') END;
END;

CREATE TRIGGER reopen_due_before_cancellation BEFORE UPDATE ON records WHEN NEW.kind='payments' AND json_extract(OLD.data,'$.status')='cleared' AND json_extract(NEW.data,'$.status')!='cleared' BEGIN
 UPDATE records SET data=json_set(data,'$.status','open','$.reopenedFrom',NEW.id),revision=revision+1,updated_at=NEW.updated_at WHERE owner=NEW.owner AND kind='installments' AND json_extract(data,'$.status')='restructured' AND id IN (SELECT installment_id FROM allocations WHERE payment_id=NEW.id AND owner=NEW.owner);
END;

CREATE TRIGGER guard_credit_issue BEFORE UPDATE ON records WHEN NEW.kind='invoices' AND json_extract(NEW.data,'$.invoiceType')='creditNote' AND json_extract(NEW.data,'$.status')='issued' AND json_extract(OLD.data,'$.status')!='issued' BEGIN
 SELECT CASE WHEN COALESCE((SELECT SUM(json_extract(data,'$.total')) FROM records WHERE owner=NEW.owner AND kind='invoices' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.invoiceType')='creditNote' AND json_extract(data,'$.status')='issued' AND json_extract(data,'$.originalId')=json_extract(NEW.data,'$.originalId')),0)+json_extract(NEW.data,'$.total')>COALESCE((SELECT json_extract(data,'$.total') FROM records WHERE id=json_extract(NEW.data,'$.originalId') AND owner=NEW.owner AND kind='invoices' AND json_extract(data,'$.status')='issued'),0) THEN RAISE(ABORT,'credit_exceeds_invoice') END;
END;

CREATE TRIGGER guard_credit_insert BEFORE INSERT ON records WHEN NEW.kind='invoices' AND json_extract(NEW.data,'$.invoiceType')='creditNote' AND json_extract(NEW.data,'$.status')='issued' BEGIN
 SELECT CASE WHEN COALESCE((SELECT SUM(json_extract(data,'$.total')) FROM records WHERE owner=NEW.owner AND kind='invoices' AND archived=0 AND json_extract(data,'$.invoiceType')='creditNote' AND json_extract(data,'$.status')='issued' AND json_extract(data,'$.originalId')=json_extract(NEW.data,'$.originalId')),0)+json_extract(NEW.data,'$.total')>COALESCE((SELECT json_extract(data,'$.total') FROM records WHERE id=json_extract(NEW.data,'$.originalId') AND owner=NEW.owner AND kind='invoices' AND json_extract(data,'$.status')='issued'),0) THEN RAISE(ABORT,'credit_exceeds_invoice') END;
END;

CREATE TRIGGER guard_withholding_payment BEFORE UPDATE ON records WHEN NEW.kind='withholdings' AND json_extract(NEW.data,'$.status')='validated' AND json_extract(OLD.data,'$.status')='draft' AND json_extract(NEW.data,'$.operation')='add' BEGIN
 SELECT CASE WHEN COALESCE((SELECT SUM(json_extract(data,'$.total')) FROM records WHERE owner=NEW.owner AND kind='withholdings' AND archived=0 AND id!=NEW.id AND json_extract(data,'$.status')!='draft' AND json_extract(data,'$.operation')='add' AND json_extract(data,'$.paymentId')=json_extract(NEW.data,'$.paymentId') AND NOT EXISTS(SELECT 1 FROM records c WHERE c.owner=NEW.owner AND c.kind='withholdings' AND c.archived=0 AND json_extract(c.data,'$.direction')=json_extract(NEW.data,'$.direction') AND json_extract(c.data,'$.reference')=json_extract(records.data,'$.reference') AND json_extract(c.data,'$.status')!='draft' AND json_extract(c.data,'$.operation') IN ('modify','cancel'))),0)+json_extract(NEW.data,'$.total')>COALESCE((SELECT json_extract(data,'$.amount') FROM records WHERE id=json_extract(NEW.data,'$.paymentId') AND owner=NEW.owner AND kind='payments' AND json_extract(data,'$.status')='cleared'),0) THEN RAISE(ABORT,'retention_exceeds_payment') END;
END;
